WITH with_latest AS (SELECT s.*, top1.order_item_unit_price, top1.quantity FROM orders s JOIN LATERAL (SELECT c.unit_price AS order_item_unit_price, c.quantity FROM order_items c WHERE c.order_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT s.id, s.customer_id, s.store_id, s.order_date, s.status, s.channel, s.amount, s.discount, s.order_item_unit_price, (SELECT AVG(t2.shipping_fee) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS avg_order_shipping_fee FROM with_latest s ORDER BY order_date;
